@Test
public void testFileSystemNotBeingClosed() throws Throwable {
    HdfsResource resourceToRead = null;
    try {
        resourceToRead = new HdfsResource(_hostname, _port, _filePath);
        resourceToRead.write(new Action<OutputStream>() {

            @Override
            public void run(OutputStream out) throws Exception {
                FileHelper.writeString(out, "testFileSystemNotBeingClosed");
            }
        });
        final MutableRef<Throwable> throwableRef = new MutableRef<>();
        Thread.UncaughtExceptionHandler exceptionHandler = new Thread.UncaughtExceptionHandler() {

            public void uncaughtException(Thread th, Throwable ex) {
                throwableRef.set(ex);
                Assert.fail("Caught exception in the thread: " + ex);
            }
        };
        Thread[] threads = new Thread[10];
        for (int i = 0; i < threads.length; i++) {
            final HdfsResource res = new HdfsResource(_hostname, _port, _filePath);
            Thread thread = new Thread(new Runnable() {

                @Override
                public void run() {
                    res.read(new Action<InputStream>() {

                        @Override
                        public void run(InputStream is) throws Exception {
                            String readAsString = FileHelper.readAsString(FileHelper.getReader(is, "UTF-8"));
                            Assert.assertNotNull(readAsString);
                            Assert.assertEquals("testFileSystemNotBeingClosed", readAsString);
                        }
                    });
                }
            });
            thread.setUncaughtExceptionHandler(exceptionHandler);
            thread.start();
            threads[i] = thread;
        }
        for (int i = 0; i < threads.length; i++) {
            threads[i].join();
        }
        Throwable error = throwableRef.get();
        if (error != null) {
            throw error;
        }
    } finally {
        if (resourceToRead != null) {
            final FileSystem fileSystem = resourceToRead.getHadoopFileSystem();
            final Path resourceToReadPath = new Path(resourceToRead.getFilepath());
            if (fileSystem.exists(resourceToReadPath)) {
                fileSystem.delete(resourceToReadPath, true);
            }
        }
    }
}

@Test
public void testTableDetection() throws Exception {
    if (!isConfigured()) {
        System.err.println(getInvalidConfigurationMessage());
        return;
    }
    // Insert a node
    requestWrapper.executeCypherQuery("CREATE (n:JUnitLabel { property1: 1, property2: 2 })");
    // Adding a node, but deleting it afterwards - should not be included in
    // the schema as the table would be empty
    requestWrapper.executeCypherQuery("CREATE (n:JUnitLabelTemp { property1: 3, property2: 4 })");
    requestWrapper.executeCypherQuery("MATCH (n:JUnitLabelTemp) DELETE n;");
    Neo4jDataContext strategy = new Neo4jDataContext(getHostname(), getPort(), getUsername(), getPassword());
    Schema schema = strategy.getSchemaByName(strategy.getDefaultSchemaName());
    // Do not check the precise count, Neo4j keeps labels forever, there are
    // probably many more than you imagine...
    List<String> tableNames = Arrays.asList(schema.getTableNames());
    logger.info("Tables (labels) detected: " + tableNames);
    assertTrue(tableNames.contains("JUnitLabel"));
    assertFalse(tableNames.contains("JUnitLabelTemp"));
    Table table = schema.getTableByName("JUnitLabel");
    List<String> columnNames = Arrays.asList(table.getColumnNames());
    assertTrue(columnNames.contains("property1"));
    assertTrue(columnNames.contains("property2"));
}

