    Column bookIdColumn = table2.getColumnByName("_id");
    Column bookTitleColumn = table2.getColumnByName("title");
    CompiledQuery query = strategy.query().from(table1).and(table2).select(personNameColumn, bookIdColumn, bookTitleColumn).where(personHasReadColumn).eq(bookIdColumn).compile();
    try (final DataSet dataSet = strategy.executeQuery(query)) {
